(()=>{
 if(location.pathname.startsWith('/admin'))return;
 const el=(tag,text='')=>{const e=document.createElement(tag);e.textContent=text;return e;};
 fetch('/api/discount-config').then(r=>r.json()).then(config=>{
  if(!config.enabled)return;
  const open=el('button',`Получить скидку ${config.amount} ₽`);open.type='button';open.id='discount';open.className='button hero-cta';const actions=document.querySelector('.hero-actions');if(!actions)return;const game=actions.querySelector('#hero-game-link');if(game)game.before(open);else actions.append(open);if(location.hash==='#discount')open.scrollIntoView({block:'center'});
  const dialog=el('dialog');dialog.style.cssText='max-width:440px;width:calc(100% - 32px);padding:24px;border:0;border-radius:20px';const close=el('button','Закрыть');close.type='button';close.onclick=()=>dialog.close();dialog.append(close,el('h2',`Получить скидку ${config.amount} ₽`),el('p','Пришлём промокод и маршрут на станцию в СМС.'));const form=el('form');
  for(const [name,label,type] of [['name','Ваше имя','text'],['phone','Телефон +7','tel']]){const l=el('label',label),i=el('input');i.name=name;i.type=type;i.required=true;i.maxLength=name==='name'?80:32;i.style.cssText='display:block;width:100%;margin:8px 0 16px;padding:12px';l.append(i);form.append(l);}
  const honey=el('input');honey.name='website';honey.hidden=true;honey.tabIndex=-1;honey.autocomplete='off';form.append(honey);
  for(const [name,label,required] of [['consent','Согласен на обработку имени и телефона и получение сервисных и информационных СМС от СТАРТ. Отказ: напишите СТОП на info@spotsup.ru.',true],['marketing','Хочу получать рекламные СМС об акциях (необязательно).',false]]){const l=el('label'),i=el('input');i.type='checkbox';i.name=name;i.required=required;l.style.cssText='display:block;margin:14px 0';l.append(i,document.createTextNode(' '+label));if(name==='consent'){const a=document.createElement('a');a.href='/privacy.html';a.target='_blank';a.textContent=' Политика конфиденциальности';l.append(a);}form.append(l);}
  const submit=el('button','Получить промокод по СМС');submit.className='button';const status=el('p');status.setAttribute('role','status');form.append(submit,status);form.onsubmit=async e=>{e.preventDefault();submit.disabled=true;try{const b=Object.fromEntries(new FormData(form));b.consent=form.elements.consent.checked;b.marketing=form.elements.marketing.checked;const params=new URLSearchParams(location.search);for(const k of ['utm_source','utm_campaign'])b[k]=params.get(k)||'';const r=await fetch('/api/discount',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});const d=await r.json();if(!r.ok)throw Error(d.error);status.textContent=d.message;if(d.ok&&!d.duplicate)window.startAnalytics?.goal('discount_request');}catch(e){status.textContent=e.message;submit.disabled=false;}};dialog.append(form);document.body.append(dialog);open.onclick=()=>dialog.showModal();
 }).catch(()=>{});
})();
